scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_345'] || []

control 'CKV_AWS_345' do
  title 'Ensure that Network firewall encryption is via a CMK'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_networkfirewall_firewall resources that actually exist, read
    through the stock inspec-aws aws_network_firewall_firewall resource.
  DESC

  desc 'rationale', <<~RATIONALE
    The firewall's stored configuration includes the rules and the addresses
    they name. On the AWS-owned key that material is encrypted but the key
    is outside the account, so its use cannot be audited or revoked here.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_networkfirewall_firewall:
    encryption_configuration/[0]/key_id is CKV_ANY;
    aws_networkfirewall_rule_group: encryption_configuration/[0]/key_id is
    CKV_ANY
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_networkfirewall_firewall:

      resource "aws_kms_key" "nfw" {
        description         = "Network Firewall configuration encryption"
        enable_key_rotation = true
      }

      resource "aws_networkfirewall_firewall" "edge" {
        name                = "edge"
        firewall_policy_arn = aws_networkfirewall_firewall_policy.edge.arn
        vpc_id              = aws_vpc.app.id

        encryption_configuration {
          key_id = aws_kms_key.nfw.arn
          type   = "CUSTOMER_KMS"
        }

        subnet_mapping {
          subnet_id = aws_subnet.firewall.id
        }
      }

    Out of band — aws_networkfirewall_firewall:

      aws network-firewall associate-firewall-policy --firewall-name edge --encryption-configuration KeyId=<key-arn>,Type=CUSTOMER_KMS

    Terraform — aws_networkfirewall_rule_group:

      resource "aws_networkfirewall_rule_group" "block" {
        name     = "block"
        type     = "STATEFUL"
        capacity = 100

        encryption_configuration {
          key_id = aws_kms_key.nfw.arn
          type   = "CUSTOMER_KMS"
        }

        rule_group {
          rules_source {
            rules_string = "drop tcp any any -> any 23 (msg:\"telnet\"; sid:1;)"
          }
        }
      }

    Out of band — aws_networkfirewall_rule_group:

      aws network-firewall update-rule-group --rule-group-name block --type STATEFUL --encryption-configuration KeyId=<key-arn>,Type=CUSTOMER_KMS --update-token <token>

    Note (aws_networkfirewall_rule_group): This profile assesses the firewall,
    not the rule group: the renderer emits one resource type per control. The
    rule-group half needs its own control before it is claimed.
  FIX

  tag checkov_id:            'CKV_AWS_345'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_networkfirewall_firewall aws_networkfirewall_rule_group]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/networkfirewall_firewall#encryption-configuration'
  tag nist:                  ['SC-12', 'SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-12', 'SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-002450', 'CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-KMG']
  tag severity:              'low'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    aws_network_firewall_firewalls(aws_region: region).firewall_names.to_a.map { |id| [id, region] }
  end

  # A plural resource whose table is built from the API response returns nil for
  # a column that does not exist, rather than raising. Passing that on gives
  # "`[:x]` must be provided" and kills the control. Blank ids are separated out
  # and asserted on below, so a wrong `ids` column is a visible failure rather
  # than a crash or a silent Not Applicable.
  unusable = found.count { |id, _r| "#{id}".strip.empty? }
  found = found.reject { |id, _r| "#{id}".strip.empty? }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_networkfirewall_firewall', rules: exempt) }

  if unusable.positive?
    describe "aws_networkfirewall_firewall enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `ids` column in resource_map.yml "          'likely names a field this resource does not expose'
      end
    end
  end

  applicable = !in_scope.empty?
  impact 0.3
  impact 0.0 unless applicable
  only_if('no aws_networkfirewall_firewall in scope') { applicable }

  in_scope.each do |id, region|
    describe aws_network_firewall_firewall(firewall_name: id, aws_region: region) do
      its('firewall.encryption_configuration.key_id') { should satisfy('be set') { |v| !v.nil? && !(v.respond_to?(:empty?) && v.empty?) } }
    end
  end
end
